"use client";

import FilterPanel from "@/components/FilterPanel";
import WorksheetPreview from "@/components/WorksheetPreview";
import { QUESTION_BANK } from "@/lib/bank";
import { CHAPTERS_REGISTRY } from "@/lib/chapters";
import { updateStudentProfileMetrics } from "@/lib/profile";
import type {
  GenerateFilters,
  StudentProfileAnalytics,
  StudentSubmissionReport,
  SubtopicAnalytics,
  Worksheet,
} from "@/lib/types";
import { useEffect, useMemo, useState } from "react";

type PastRecord = {
  id: string;
  submittedAt: string;
  chapterTitle: string;
  totalQuestions: number;
  scoreObtained: number;
  maxPossibleMarks: number;
  accuracyPercentage: number;
};

function getHeatmapCellClass(stats?: SubtopicAnalytics) {
  if (!stats || stats.timesTested === 0) {
    return "border-zinc-200 bg-zinc-200 text-zinc-600";
  }

  if (stats.accuracyPercentage >= 75) {
    return "border-emerald-400 bg-emerald-400 text-emerald-950";
  }

  if (stats.accuracyPercentage >= 55) {
    return "border-yellow-300 bg-yellow-300 text-yellow-900";
  }

  return "border-rose-200 bg-rose-200 text-rose-900";
}

export default function Home() {
  const [isMounted, setIsMounted] = useState(false);
  const [worksheet, setWorksheet] = useState<Worksheet | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [studentName, setStudentName] = useState("");
  const [profileNameInput, setProfileNameInput] = useState("");
  const [profile, setProfile] = useState<StudentProfileAnalytics | null>(null);
  const [pastRecords, setPastRecords] = useState<PastRecord[]>([]);

  useEffect(() => {
    // Browser extensions can mutate form fields during hydration.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setIsMounted(true);
  }, []);

  useEffect(() => {
    const activeStudent = localStorage.getItem("active_student_session");
    if (!activeStudent) {
      return;
    }

    // eslint-disable-next-line react-hooks/set-state-in-effect
    setStudentName(activeStudent);
    const storedProfile = localStorage.getItem(`student_profile_${activeStudent.trim().toLowerCase()}`);
    if (storedProfile) {
      setProfile(JSON.parse(storedProfile) as StudentProfileAnalytics);
    }

    const storedRecords = localStorage.getItem(
      `student_records_${activeStudent.trim().toLowerCase()}`,
    );
    setPastRecords(storedRecords ? (JSON.parse(storedRecords) as PastRecord[]) : []);
  }, []);

  const chapterRows = useMemo(
    () =>
      CHAPTERS_REGISTRY.map((chapter) => {
        const subtopics = Array.from(
          new Set(
            QUESTION_BANK.filter((question) => question.chapter === chapter.id).map(
              (question) => question.subtopic ?? question.topic,
            ),
          ),
        );

        return {
          id: chapter.id,
          title: chapter.title,
          subtopics,
        };
      }),
    [],
  );

  if (!isMounted) {
    return <div className="mx-auto min-h-screen w-full max-w-6xl px-4 py-8" />;
  }

  function handleProfileSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const trimmedName = profileNameInput.trim();
    if (!trimmedName) return;

    setStudentName(trimmedName);
    localStorage.setItem("active_student_session", trimmedName);

    const storedProfile = localStorage.getItem(`student_profile_${trimmedName.toLowerCase()}`);
    const storedRecords = localStorage.getItem(`student_records_${trimmedName.toLowerCase()}`);
    setPastRecords(storedRecords ? (JSON.parse(storedRecords) as PastRecord[]) : []);
    if (storedProfile) {
      setProfile(JSON.parse(storedProfile) as StudentProfileAnalytics);
      return;
    }

    setProfile({
      studentName: trimmedName,
      createdAt: new Date().toISOString(),
      worksheetsCompleted: 0,
      overallAccuracy: 0,
      syllabusHeatmap: {},
      identifiedWeakPoints: [],
    });
  }

  function handleProfileSignOut() {
    localStorage.removeItem("active_student_session");
    setStudentName("");
    setProfile(null);
    setProfileNameInput("");
    setPastRecords([]);
  }

  function buildMockReportFromWorksheet(currentWorksheet: Worksheet): StudentSubmissionReport {
    const responses = currentWorksheet.questions.map((question, index) => {
      const isCorrect = (index + question.marks) % 2 === 0;
      return {
        questionId: question.id,
        questionText: question.stem,
        studentAnswer: isCorrect ? question.answer : "Not attempted",
        correctAnswer: question.answer,
        isCorrect,
        marksAwarded: isCorrect ? question.marks : 0,
      };
    });

    const scoreObtained = responses.reduce((sum, response) => sum + response.marksAwarded, 0);
    const maxPossibleMarks = currentWorksheet.questions.reduce((sum, question) => sum + question.marks, 0);

    return {
      submissionId: crypto.randomUUID(),
      worksheetId: currentWorksheet.id,
      chapterId: currentWorksheet.filters.chapter,
      submittedAt: new Date().toISOString(),
      totalQuestions: currentWorksheet.questions.length,
      scoreObtained,
      maxPossibleMarks,
      accuracyPercentage: maxPossibleMarks > 0 ? Math.round((scoreObtained / maxPossibleMarks) * 100) : 0,
      responses,
    };
  }

  function handleReportSubmission(report: StudentSubmissionReport) {
    if (!studentName.trim()) return;

    const nextProfile = updateStudentProfileMetrics(studentName.trim(), report, QUESTION_BANK);
    setProfile(nextProfile);

    const chapter = CHAPTERS_REGISTRY.find((item) => item.id === report.chapterId);
    const nextRecord: PastRecord = {
      id: report.submissionId,
      submittedAt: report.submittedAt,
      chapterTitle: chapter?.title ?? report.chapterId,
      totalQuestions: report.totalQuestions,
      scoreObtained: report.scoreObtained,
      maxPossibleMarks: report.maxPossibleMarks,
      accuracyPercentage: report.accuracyPercentage,
    };
    const nextRecords = [nextRecord, ...pastRecords].slice(0, 12);
    setPastRecords(nextRecords);
    localStorage.setItem(
      `student_records_${studentName.trim().toLowerCase()}`,
      JSON.stringify(nextRecords),
    );
  }

  async function handleGenerate(filters: GenerateFilters) {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch("/api/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(filters),
      });
      if (!res.ok) throw new Error("Generate failed");

      const data = (await res.json()) as Worksheet;
      setWorksheet(data);

      if (studentName.trim()) {
        const nextReport = buildMockReportFromWorksheet(data);
        handleReportSubmission(nextReport);
      }
    } catch {
      setError("Could not generate worksheet. Try again.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="mx-auto min-h-screen w-full max-w-6xl px-4 py-8">
      <div className="no-print mb-6 rounded-2xl border border-zinc-200 bg-white p-4 shadow-sm">
        {studentName ? (
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-full bg-zinc-900 text-sm font-semibold text-white">
                {studentName.slice(0, 1).toUpperCase()}
              </div>
              <div>
                <p className="text-xs uppercase tracking-[0.22em] text-zinc-400">Active profile</p>
                <p className="text-lg font-semibold text-zinc-900">{studentName}</p>
              </div>
            </div>
            <button
              type="button"
              onClick={handleProfileSignOut}
              className="text-sm font-medium text-zinc-600 underline decoration-zinc-300 underline-offset-4 hover:text-zinc-900"
            >
              Sign Out / Switch Profile
            </button>
          </div>
        ) : (
          <form onSubmit={handleProfileSubmit} className="flex flex-col gap-3 sm:flex-row sm:items-center">
            <label className="sr-only" htmlFor="student-name-entry">
              Student Name
            </label>
            <input
              id="student-name-entry"
              value={profileNameInput}
              onChange={(event) => setProfileNameInput(event.target.value)}
              placeholder="Enter Student Name to Track Performance Progress"
              className="h-12 flex-1 rounded-xl border border-zinc-200 bg-zinc-50 px-4 text-sm text-zinc-900 placeholder:text-zinc-400 focus:border-zinc-400 focus:outline-none focus:ring-2 focus:ring-zinc-200"
            />
            <button
              type="submit"
              className="h-12 rounded-xl bg-zinc-900 px-5 text-sm font-medium text-white transition hover:bg-zinc-700"
            >
              Save
            </button>
          </form>
        )}
      </div>

      {profile && profile.identifiedWeakPoints.length > 0 && (
        <div className="no-print mb-6 rounded-2xl border border-red-200 bg-red-50 p-4 shadow-sm">
          <p className="mb-3 text-sm font-semibold uppercase tracking-[0.2em] text-red-700">
            Weak Points Alert
          </p>
          <div className="space-y-2">
            {profile.identifiedWeakPoints.map((weakPoint, index) => (
              <div key={`${weakPoint.chapterId}-${weakPoint.subtopicName}-${index}`} className="rounded-xl border border-red-200 bg-white/80 px-3 py-2 text-sm text-red-800">
                <span className="font-semibold">⚠️ Critical Blindspot Detected:</span> {weakPoint.subtopicName} — {weakPoint.reason} Recommended Action: Generate a focused Hard-difficulty worksheet for this specific topic node.
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="no-print mb-8 flex flex-wrap items-end justify-between gap-4">
        <div>
          <p className="text-sm text-zinc-500">Worksheet generator</p>
          <h1 className="text-3xl font-semibold tracking-tight text-zinc-900">
            NCERT practice sheets
          </h1>
        </div>
        {worksheet && (
          <button
            type="button"
            onClick={() => window.print()}
            className="rounded-lg border border-zinc-300 bg-white px-4 py-2 text-sm font-medium text-zinc-800 hover:bg-zinc-50"
          >
            Print / Save PDF
          </button>
        )}
      </div>

      {error && (
        <p className="no-print mb-4 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">
          {error}
        </p>
      )}

      <section className="no-print mb-6 rounded-2xl border border-zinc-200 bg-white p-5 shadow-sm">
        <div className="mb-4 flex items-center justify-between gap-3">
          <div>
            <p className="text-xs uppercase tracking-[0.22em] text-zinc-400">Performance map</p>
            <h2 className="text-xl font-semibold text-zinc-900">Syllabus Heatmap Tracking</h2>
          </div>
          <div className="rounded-full bg-zinc-100 px-3 py-1 text-xs font-medium text-zinc-700">
            {profile ? `${profile.worksheetsCompleted} worksheets` : "No profile"}
          </div>
        </div>

        <div className="space-y-4">
          {chapterRows.map((chapter) => {
            const chapterStats = profile?.syllabusHeatmap?.[chapter.id] ?? {};

            return (
              <div key={chapter.id} className="rounded-xl border border-zinc-200 bg-zinc-50 p-3">
                <div className="mb-2 flex items-center justify-between gap-3">
                  <span className="text-sm font-semibold text-zinc-800">{chapter.title}</span>
                  <span className="text-xs text-zinc-500">{chapter.subtopics.length} nodes</span>
                </div>
                <div className="flex flex-wrap gap-2">
                  {chapter.subtopics.map((subtopic) => {
                    const stats = chapterStats[subtopic];
                    const accuracy = stats?.accuracyPercentage ?? 0;
                    const isUntouched = !stats || stats.timesTested === 0;

                    return (
                      <div
                        key={`${chapter.id}-${subtopic}`}
                        title={
                          isUntouched
                            ? `${subtopic}: Untouched topic area`
                            : `${subtopic}: ${accuracy}% accuracy across ${stats.timesTested} attempts`
                        }
                        className={`flex h-9 w-9 items-center justify-center rounded-md border text-[10px] font-medium ${getHeatmapCellClass(stats)}`}
                      >
                        {isUntouched ? "" : `${accuracy}%`}
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </section>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
        <div className="lg:col-span-1">
          <FilterPanel onGenerate={handleGenerate} loading={loading} />
        </div>
        <div className="lg:col-span-2">
          <WorksheetPreview worksheet={worksheet} />
        </div>
      </div>

      <section className="no-print mt-8 rounded-2xl border border-zinc-200 bg-white p-5 shadow-sm">
        <div className="mb-4 flex items-center justify-between gap-3">
          <div>
            <p className="text-xs uppercase tracking-[0.22em] text-zinc-400">Progress archive</p>
            <h2 className="text-xl font-semibold text-zinc-900">Past Records</h2>
          </div>
          <span className="text-xs text-zinc-500">{pastRecords.length} saved</span>
        </div>
        {pastRecords.length === 0 ? (
          <p className="text-sm text-zinc-500">
            Generate a worksheet with an active student profile to start your record.
          </p>
        ) : (
          <div className="divide-y divide-zinc-100">
            {pastRecords.map((record) => (
              <div key={record.id} className="flex flex-wrap items-center justify-between gap-3 py-3 first:pt-0 last:pb-0">
                <div>
                  <p className="font-medium text-zinc-800">{record.chapterTitle}</p>
                  <p className="text-xs text-zinc-500">
                    {new Date(record.submittedAt).toLocaleString()} · {record.totalQuestions} questions
                  </p>
                </div>
                <div className="text-right text-sm">
                  <p className="font-semibold text-zinc-900">
                    {record.scoreObtained}/{record.maxPossibleMarks} marks
                  </p>
                  <p className="text-xs text-zinc-500">{record.accuracyPercentage}% accuracy</p>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>
    </main>
  );
}
